// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        // withdraw uses transfer(): requires c's balance >= amount and msg.value == 0
        vm.assume(amount > 0);
        vm.assume(amount <= address(c).balance + 1e30);
        vm.deal(address(c), amount); // ensure the transfer always succeeds on the reference

        // owner is msg.sender at deploy == this test contract, so call directly
        uint256 callerBefore = address(this).balance;

        c.withdraw(amount);

        // General rule: the caller receives exactly the full requested amount.
        assertTrue(address(this).balance == callerBefore + amount);
    }

    receive() external payable {}
}
